INSERT INTO repo_guardrails (guardrail_id, guardrail_level, topic, allowed_concepts, excluded_claims, evidence_type, status) VALUES ('GR_COURSE_051', 'Course', 'Environmental Impact Assessment Law', 'statutory basis; regulatory instruments; project categories; competent authorities; screening; terms of reference; baseline requirements; alternatives; impact prediction; cumulative impacts; risk; mitigation hierarchy; notice; disclosure; hearings; submissions; procedural fairness; appraisal committees; conditions; reasoned decisions; judicial review; conditions; monitoring; reporting; non-compliance; adaptive management; standing; remedies; evidentiary issues; comparative EIA regimes', 'Detailed engineering design, laboratory methods, and environmental modelling are outside the legal guardrail unless they are explicitly used as evidence or technical inputs to an EIA decision, compliance determination, or legal dispute.', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_052', 'Course', 'Climate Change Law and Policy', 'climate institutions; legislative instruments; executive policy; federalism; emissions regulation; carbon pricing concepts; energy regulation; sectoral measures; adaptation duties; disaster risk; resilience planning; vulnerable communities; climate risk disclosure; sustainable finance; fiduciary considerations; reporting; UNFCCC; Paris Agreement; nationally determined contributions; transparency framework; rights-based claims; government duties; corporate claims; causation; policy instruments; regulatory coordination; monitoring; evaluation', 'Climate-system modelling, emissions measurement, and engineering design are outside the legal-policy guardrail unless explicitly used as evidence, regulatory inputs, disclosure requirements, or implementation mechanisms.', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_053', 'Course', 'Contract Law and Commercial Agreements', 'offer; acceptance; consideration; intention; capacity; consent; express terms; implied terms; conditions and warranties; interpretation; exclusion clauses; performance; frustration; novation; alteration; discharge by agreement; anticipatory breach; damages; specific performance; injunctions; restitution; indemnities; limitation clauses; guarantees; force majeure; insurance clauses; definitions; representations; covenants; schedules; negotiation strategy; sale of goods; services; technology agreements; confidentiality; dispute clauses', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_054', 'Course', 'Labour and Employment Law', 'employment status; appointment terms; working conditions; standing orders; wage regulation; deductions; bonus; social security; leave; trade unions; collective bargaining; industrial disputes; strikes and lockouts; workplace safety; working hours; welfare; employer duties; non-discrimination; harassment; maternity protections; reasonable workplace protections; conciliation; labour authorities; tribunals; judicial remedies; platform work; fixed-term work; contract labour; remote work; compliance systems', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_055', 'Course', 'Corporate, Sustainability and ESG Law', 'company organs; governance structures; shareholder rights; disclosure; fiduciary duties; care; conflict management; related-party transactions; corporate environmental duties; labour rights; community impacts; supply-chain responsibility; materiality; non-financial disclosure; sustainability reporting; assurance concepts; green finance; climate risk; transition risk; due diligence; compliance programs; investigations; whistleblowing; sanctions; greenwashing; stakeholder claims; disclosure liability; contractual ESG clauses', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_056', 'Course', 'Sociology', 'classical theory; functionalism; conflict theory; symbolic interactionism; family; education; religion; economy; polity; institutional change; culture; norms; values; identity; socialization; deviance; class; status; gender; race/ethnicity as social structure; mobility; poverty; primary/secondary groups; organizations; bureaucracy; social networks; demography; migration; urbanization; globalization; social movements; digital society; institutions and technology; comparative analysis; mixed-method sociology', 'Clinical diagnosis, individual psychotherapy, and purely biological explanations of behaviour are outside the sociological guardrail; economic, political, or technological concepts should be included only where they are analysed as social structures, institutions, or processes.', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_057', 'Course', 'Social Psychology', 'schemas; attribution; heuristics; social perception; judgment; attitude formation; cognitive dissonance; persuasion models; resistance; attraction; relationships; prosocial behaviour; aggression; conflict; group norms; conformity; obedience; group decision-making; collective action; social identity; categorization; prejudice; stereotyping; intergroup conflict; normative influence; informational influence; communication; misinformation; health; organizations; education; environmental behaviour; interventions', 'Clinical diagnosis and treatment, purely individual personality assessment, and macroeconomic or macro-level policy analysis are outside the social-psychology guardrail unless an explicit social-psychological mechanism is being studied.', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_058', 'Course', 'Development Economics', 'growth models; productivity; structural change; industrialization; poverty measurement; inequality measures; redistribution; multidimensional poverty; education; health; labour markets; returns to human capital; property rights; governance; political economy; institutional quality; credit constraints; financial inclusion; market failures; informal institutions; program design; cost-benefit analysis; impact evaluation; randomized trials; trade; aid; migration; technology transfer; global value chains', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_059', 'Course', 'Public Policy and Governance', 'policy problems; institutions; actors; policy instruments; agenda setting; problem definition; evidence use; policy design; stakeholder analysis; implementation structures; administrative capacity; street-level bureaucracy; coordination; regulatory institutions; accountability; transparency; participation; regulatory design; budgets; public expenditure; fiscal instruments; procurement; resource allocation; process evaluation; outcome evaluation; impact evaluation; cost-effectiveness; digital public services; data governance; algorithmic decision-making; platform regulation', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_COURSE_060', 'Course', 'Research Methods in Social Sciences', 'research questions; theory and hypotheses; exploratory/descriptive/explanatory designs; probability sampling; non-probability sampling; measurement scales; instrument design; interviews; focus groups; observation; ethnography; thematic analysis; descriptive statistics; regression; hypothesis testing; causal inference basics; sequential designs; convergent designs; triangulation; integration; construct validity; internal validity; external validity; reliability; reflexivity; informed consent; confidentiality; research ethics review; data management; reproducibility', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_MOD_COURSE_001_M01', 'Module', 'Foundations & Linear Data Structures', 'classes; objects; encapsulation; state and behaviour; abstraction; implementation of abstract data types; LIFO operations; push/pop; stack representation; expression processing; backtracking', '', 'Curriculum-derived disciplinary scope', 'Active'), ('GR_MOD_COURSE_001_M02', 'Module', 'Linear Data Structures', 'FIFO operations; queue represe